        "hourly": {
          "time": "array<string>",
          "pm10": "array<number>",
          "pm2_5": "array<number>"
        }
      }
    }
  },
  "sink_url": "http://recorder:8090/sink/ca3c4412_1?attempt=0",
  "sink_body": "JSON array of record objects (or {\"records\": [...]})",
